const CourseWeekDef _year2EnglishWeek1 = CourseWeekDef(
  id: "course-year2-english-w1",
  weekNumber: 1,
  titleEn: "Joining Words: and, but, because",
  titleMy: "ချိတ်ဆက်စကားလုံးများ -- and, but, because",
  xpReward: 20,
