        QuizQuestion(
          questionEn: "What is cross-text synthesis?",
          questionMy: "Cross-text synthesis ဆိုသည်မှာ အဘယ်နည်း။",
          optionsEn: [
            "Combining ideas from multiple texts into one coherent response",
            "Copying one text exactly",
            "Reading only the shortest text",
            "Ignoring differences between texts",
